    Source: packages/compose-gen/specs/organisms/feature-grid.json
    A section with a heading and the features as a grid of cards or tiles, or as rows with a picture. Icons are Lucide names. Axes: layout (grid, rows), columns, item (card, tile, cell: bordered tile with a round icon), media side (rows), density, tone.
    Props (p): id, title, features, empty, action, layout, cols, item, mediaSide, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_features = ($p['features'] ?? null)}
{var $v_empty = ($p['empty'] ?? '')}
{var $v_action = ($p['action'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'grid')}
{var $v_cols = ($p['cols'] ?? '1-3')}
{var $v_item = ($p['item'] ?? 'card')}
{var $v_mediaSide = ($p['mediaSide'] ?? 'end')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{if og_t(og_eq($v_item, 'cell'))}
  {capture $c_4}
    {capture $c_3}
      {capture $c_1}
        {=og_text($v_title)}
      {/capture}
      {=og_include('compose/Title.latte', ['as' => 2, 'size' => 'sm', 'weight' => 'semibold', 'class' => 'leading-7', 'attrs' => og_attrs(['id', og_add($v_id, '-title')]), 'children' => (string) $c_1])|noescape}
      {if og_t(og_and([og_get($v_action, ['label']), og_get($v_action, ['href'])]))}
        {capture $c_2}
          {=og_text(og_get($v_action, ['label']))}
        {/capture}
        {=og_include('compose/Link.latte', ['href' => og_url(og_s(og_get($v_action, ['href']))), 'variant' => 'default', 'class' => og_s(og_cnv([og_preset('blocks/presets/defaults.json', ['text', 'tiny']), 'shrink-0 font-medium leading-5'])), 'attrs' => og_attrs(['data-slot', 'section-action']), 'children' => (string) $c_2])|noescape}
      {/if}
    {/capture}
    {=og_include('compose/Group.latte', ['gap' => '4', 'align' => 'center', 'justify' => 'between', 'class' => 'w-full', 'children' => (string) $c_3])|noescape}
    {if og_t(og_eq(og_len($v_features), 0))}
      {=og_include('blocks/empty-state.latte', ['p' => ['icon' => 'layout-grid', 'title' => $v_empty]])|noescape}
    {else}
      {=og_include('blocks/feature-cards.latte', ['p' => ['features' => $v_features, 'cols' => $v_cols, 'item' => $v_item]])|noescape}
    {/if}
  {/capture}
  {=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'tone' => $v_tone, 'density' => $v_density, 'measure' => 'fill', 'className' => og_cnv(['py-0']), 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_4)])|noescape}
{else}
  {capture $c_5}
    {if og_t(og_eq(og_len($v_features), 0))}
      {=og_include('blocks/empty-state.latte', ['p' => ['icon' => 'layout-grid', 'title' => $v_empty]])|noescape}
    {elseif og_t(og_eq($v_layout, 'rows'))}
      {=og_include('blocks/feature-rows.latte', ['p' => ['features' => $v_features, 'mediaSide' => $v_mediaSide]])|noescape}
    {else}
      {=og_include('blocks/feature-cards.latte', ['p' => ['features' => $v_features, 'cols' => $v_cols, 'item' => $v_item]])|noescape}
    {/if}
  {/capture}
  {=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'action' => $v_action, 'tone' => $v_tone, 'density' => $v_density, 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_5)])|noescape}
